    43  static void start_server(void) {
    44      running = UA_Boolean_new();
    45      *running = true;
    46      config = UA_ServerConfig_new_default();
    47      server = UA_Server_new(config);
    48      UA_Server_run_startup(server);
    49      pthread_create(&server_thread, NULL, serverloop, NULL);
    50  }
    51
    52  static void teardown_server(void) {
    53      *running = false;
    54      pthread_join(server_thread, NULL);
    55      UA_Server_run_shutdown(server);
    56      UA_Boolean_delete(running);
    57      UA_Server_delete(server);
    58      UA_ServerConfig_delete(config);
    59  }
