    61  static void emptyCorpusDir(void) {
    62      DIR *theFolder = opendir(UA_CORPUS_OUTPUT_DIR);
    63      struct dirent *next_file;
    64      char filepath[400];
    65
    66      while ( (next_file = readdir(theFolder)) != NULL ) {
    67          // build the path for each file in the folder
    68          sprintf(filepath, "%s/%s", UA_CORPUS_OUTPUT_DIR, next_file->d_name);
    69          remove(filepath);
    70      }
    71      closedir(theFolder);
    72  }
