    82  static UA_StatusCode
    83  findServersRequest(UA_Client *client) {
    84      UA_ApplicationDescription* applicationDescriptionArray = NULL;
    85      size_t applicationDescriptionArraySize = 0;
    86
    87      size_t serverUrisSize = 1;
    88      UA_String *serverUris = UA_String_new();
    89      serverUris[0] = UA_String_fromChars("urn:some:server:uri");
    90
    91      size_t localeIdsSize = 1;
    92      UA_String *localeIds = UA_String_new();
    93      localeIds[0] = UA_String_fromChars("en");
    94
    95      ASSERT_GOOD(UA_Client_findServers(client, "opc.tcp://localhost:4840",
    96                                    serverUrisSize, serverUris, localeIdsSize, localeIds,
    97                                    &applicationDescriptionArraySize, &applicationDescriptionArray));
    98
    99      UA_Array_delete(serverUris, serverUrisSize, &UA_TYPES[UA_TYPES_STRING]);
   100      UA_Array_delete(localeIds, localeIdsSize, &UA_TYPES[UA_TYPES_STRING]);
   101      UA_Array_delete(applicationDescriptionArray, applicationDescriptionArraySize,
   102                      &UA_TYPES[UA_TYPES_APPLICATIONDESCRIPTION]);
   103
   104      return UA_STATUSCODE_GOOD;
   105  }
