   180  static UA_StatusCode
   181  registerServer2Request(UA_Client *client) {
   182      /* Prepare the request. Do not cleanup the request after the service call,
   183       * as the members are stack-allocated or point into the server config. */
   184      UA_RegisterServer2Request request;
   185      UA_RegisterServer2Request_init(&request);
   186      request.requestHeader.timestamp = UA_DateTime_now();
   187      request.requestHeader.timeoutHint = 10000;
   188
   189      initUaRegisterServer(&request.server);
   190
   191      UA_MdnsDiscoveryConfiguration mdnsConfig;
   192      UA_MdnsDiscoveryConfiguration_init(&mdnsConfig);
   193
   194      request.discoveryConfigurationSize = 1;
   195      request.discoveryConfiguration = UA_ExtensionObject_new();
   196      UA_ExtensionObject_init(&request.discoveryConfiguration[0]);
   197      request.discoveryConfiguration[0].encoding = UA_EXTENSIONOBJECT_DECODED_NODELETE;
   198      request.discoveryConfiguration[0].content.decoded.type = &UA_TYPES[UA_TYPES_MDNSDISCOVERYCONFIGURATION];
   199      request.discoveryConfiguration[0].content.decoded.data = &mdnsConfig;
   200
   201      mdnsConfig.mdnsServerName = server->config.mdnsServerName;
   202      mdnsConfig.serverCapabilities = server->config.serverCapabilities;
   203      mdnsConfig.serverCapabilitiesSize = server->config.serverCapabilitiesSize;
   204
   205      // First try with RegisterServer2, if that isn't implemented, use RegisterServer
   206      UA_RegisterServer2Response response;
   207      UA_RegisterServer2Response_init(&response);
   208      __UA_Client_Service(client, &request, &UA_TYPES[UA_TYPES_REGISTERSERVER2REQUEST],
   209                          &response, &UA_TYPES[UA_TYPES_REGISTERSERVER2RESPONSE]);
   210
   211      ASSERT_GOOD(response.responseHeader.serviceResult);
   212      UA_free(request.server.discoveryUrls);
   213      UA_ExtensionObject_delete(request.discoveryConfiguration);
   214
   215      UA_RegisterServer2Response_deleteMembers(&response);
   216
   217      return UA_STATUSCODE_GOOD;
   218  }
